import itertools

def solve_small(N):
    S = list(range(1, N + 1))
    def works(A):
        for x, y, z in itertools.combinations(A, 3):
            # Check if x,y,z can be a,b,c
            # x=a+b, y=b+c, z=c+a
            # 2a = x-y+z, 2b = x+y-z, 2c = -x+y+z
            # Need a,b,c to be distinct integers in S.
            if (x + y + z) % 2 == 0:
                a2 = x - y + z
                b2 = x + y - z
                c2 = -x + y + z
                if a2 % 2 == 0 and b2 % 2 == 0 and c2 % 2 == 0:
                    a, b, c = a2 // 2, b2 // 2, c2 // 2
                    if a != b and b != c and a != c and 1 <= a <= N and 1 <= b <= N and 1 <= c <= N:
                        return True
        return False

    for k in range(1, N + 1):
        all_work = True
        for A in itertools.combinations(S, k):
            if not works(A):
                all_work = False
                break
        if all_work:
            return k
    return N + 1

for N in range(1, 15):
    print(f"N={N}, k={solve_small(N)}")

